'use client';

import { useEffect, useRef, useState } from 'react';
import Link from 'next/link';
import { resolveImageUrl } from '@/shared/types/menu';
import { useRestaurantGuestPaths } from '@/shared/routing/restaurant-guest-path';
import { useAuthStore } from '@/store/auth.store';
import { useRestaurantStylingOptional } from '../context/RestaurantStylingContext';
import { useMenuCategoryNavOptional } from '../context/MenuCategoryNavContext';
import { MenuCategoryNav } from './MenuCategoryNav';
import { RestaurantCartButton } from './RestaurantCartButton';

interface RestaurantPublicHeaderProps {
  restaurantId: string;
  restaurantName: string;
  logoUrl?: string | null;
  onOpenCart?: () => void;
  disableScrollHide?: boolean;
}

export function RestaurantPublicHeader({
  restaurantId,
  restaurantName,
  logoUrl,
  onOpenCart,
  disableScrollHide = false,
}: RestaurantPublicHeaderProps) {
  const user = useAuthStore((s) => s.user);
  const logout = useAuthStore((s) => s.logout);
  const paths = useRestaurantGuestPaths(restaurantId);
  const { styling } = useRestaurantStylingOptional();
  const navContext = useMenuCategoryNavOptional();
  const headerBehavior = styling?.headerBehavior ?? 'sticky';

  const [hidden, setHidden] = useState(false);
  const lastScrollY = useRef(0);

  const isCategoryDockable =
    navContext !== null &&
    (navContext.mode === 'dock_in_header' || navContext.mode === 'always_in_header');

  const showHeaderCategoryNav =
    navContext !== null &&
    (navContext.mode === 'always_in_header' ||
      (navContext.mode === 'dock_in_header' && navContext.docked));

  useEffect(() => {
    if (disableScrollHide || headerBehavior !== 'hide-on-scroll') {
      setHidden(false);
      return;
    }

    const onScroll = () => {
      const currentY = window.scrollY;
      const pastThreshold = currentY > 80;
      const scrollingDown = currentY > lastScrollY.current;

      if (pastThreshold && scrollingDown) {
        setHidden(true);
      } else if (!scrollingDown || !pastThreshold) {
        setHidden(false);
      }

      lastScrollY.current = currentY;
    };

    window.addEventListener('scroll', onScroll, { passive: true });
    return () => window.removeEventListener('scroll', onScroll);
  }, [disableScrollHide, headerBehavior]);

  const isGuestOfRestaurant =
    user?.role === 'user' && user.restaurantId === restaurantId;

  return (
    <header
      className={`glass-header${hidden ? ' glass-header--hidden' : ''}${
        isCategoryDockable ? ' glass-header--category-dockable' : ''
      }${showHeaderCategoryNav ? ' glass-header--category-docked' : ''}`}
    >
      <div className="glass-header__brand">
        {logoUrl && (
          <img
            className="glass-header__logo"
            src={resolveImageUrl(logoUrl)}
            alt=""
          />
        )}
        <span className="glass-header__brand-name">{restaurantName}</span>
      </div>

      {isCategoryDockable && (
        <div
          className={`glass-header__category-nav${
            showHeaderCategoryNav ? ' glass-header__category-nav--visible' : ''
          }`}
        >
          <MenuCategoryNav placement="header" />
        </div>
      )}

      <div className="glass-header__actions">
        {onOpenCart && (
          <RestaurantCartButton restaurantId={restaurantId} onOpen={onOpenCart} />
        )}
        {isGuestOfRestaurant ? (
          <>
            <Link href={paths.account} className="glass-header__link">
              {user.firstName}
            </Link>
            <button
              type="button"
              className="glass-header__link"
              onClick={logout}
            >
              Выйти
            </button>
          </>
        ) : (
          <Link href={paths.auth()} className="glass-header__link">
            Войти
          </Link>
        )}
      </div>
    </header>
  );
}
