'use client';

import { useEffect, useRef, useState } from 'react';
import { RestaurantPublicHeader } from './RestaurantPublicHeader';
import { useRestaurantStylingOptional } from '../context/RestaurantStylingContext';

interface RestaurantPublicHeaderStackProps {
  restaurantId: string;
  restaurantName: string;
  logoUrl?: string | null;
  onOpenCart?: () => void;
}

export function RestaurantPublicHeaderStack({
  restaurantId,
  restaurantName,
  logoUrl,
  onOpenCart,
}: RestaurantPublicHeaderStackProps) {
  const { styling } = useRestaurantStylingOptional();
  const headerBehavior = styling?.headerBehavior ?? 'sticky';
  const [hidden, setHidden] = useState(false);
  const lastScrollY = useRef(0);

  useEffect(() => {
    if (headerBehavior !== 'hide-on-scroll') {
      setHidden(false);
      return;
    }

    const onScroll = () => {
      const currentY = window.scrollY;
      const pastThreshold = currentY > 80;
      const scrollingDown = currentY > lastScrollY.current;

      if (pastThreshold && scrollingDown) {
        setHidden(true);
      } else if (!scrollingDown || !pastThreshold) {
        setHidden(false);
      }

      lastScrollY.current = currentY;
    };

    window.addEventListener('scroll', onScroll, { passive: true });
    return () => window.removeEventListener('scroll', onScroll);
  }, [headerBehavior]);

  return (
    <div
      className={`restaurant-public__header-stack${
        hidden ? ' restaurant-public__header-stack--hidden' : ''
      }`}
    >
      <RestaurantPublicHeader
        restaurantId={restaurantId}
        restaurantName={restaurantName}
        logoUrl={logoUrl}
        onOpenCart={onOpenCart}
        disableScrollHide
      />
    </div>
  );
}
